#[derive(Deserialize)]
struct RecordedObservation {
    schema_version: String,
    preview_id: String,
    applied_events: Vec<DesiredEvent>,
    observed_events: Vec<DesiredEvent>,
    conflicts: Vec<CalendarConflict>,
    #[serde(default)]
    out_of_range_events: Vec<DesiredEvent>,
}

fn internal(error: impl std::fmt::Display) -> AppError {
    AppError::Internal(error.to_string())
}

pub async fn reconcile(
    state: &AppState,
    mode: CalendarExportMode,
) -> Result<CalendarReconcileResponse> {
    mode.ensure_available(state)?;
    let _guard = state.inner().calendar_projection_lock.lock().await;
    let pool = state.inner().store.pool();
    let applied = calendar_apply::last_applied_events(pool).await?;
    // Match last_applied_events' schema/status/order exactly for source links.
    let previous = sqlx::query("SELECT id, preview_id FROM projection_results WHERE status IN ('applied','partial') AND json_extract(payload_json,'$.schema_version')=? ORDER BY rowid DESC LIMIT 1")
        .bind(CALENDAR_PROJECTION_RESULT_SCHEMA_VERSION).fetch_optional(pool).await.map_err(internal)?;
    let result_id: Option<String> = previous
        .as_ref()
        .map(|row| row.try_get("id"))
        .transpose()
        .map_err(internal)?;
    // Before the first apply there is no source preview. Reserve a correctly
    // typed bookkeeping id for the existing NOT NULL preview_id columns; this
    // does not create a preview, invent ownership, or claim a prior delivery.
    let preview_id: String = previous
        .as_ref()
        .map(|row| row.try_get("preview_id"))
        .transpose()
        .map_err(internal)?
        .unwrap_or_else(|| UbuId::new(ObjectType::ProjectionPreview).to_string());
    let google = if mode == CalendarExportMode::Live {
        Some(Arc::new(
            GoogleCalendarApi::new(&state.inner().config).map_err(internal)?,
        ))
    } else {
        None
    };
    let client: Arc<dyn CalendarApi> = match &google {
        Some(client) => client.clone(),
        None => state.mock_calendar_api(&applied),
    };
    let range = super::calendar_range::CalendarTimeRange::planning(state).await?;
    let (applied, out_of_range_events): (Vec<_>, Vec<_>) = applied.into_iter().partition(|event| range.overlaps(event));
    let mut observed = client.list_events(&range).await.map_err(AppError::Upstream)?;
    super::calendar_capture::normalize_observed(&mut observed, &applied);
    let ubu_created_ids = client.take_ubu_created_ids().await;
    let mut diagnostics = client.take_diagnostics().await;
    for (source, (row, payload)) in super::calendar_sources::by_source(pool).await? {
        if row.status != "active" || observed.iter().any(|event| event.external_id == source) { continue; }
        // A bounded observation says nothing about commitments outside its range.
        let in_range = payload["static_window"]["start"].as_str().zip(payload["static_window"]["end"].as_str())
            .and_then(|(start,end)| super::calendar_range::CalendarTimeRange::parse(start,end).ok())
            .is_some_and(|window| window.start < range.end && window.end > range.start);
        if in_range {
            diagnostics.push(crate::api::planning::DiagnosticBody {
                code: "capture_source_removed".into(),
                message: format!("Captured Task `{}` has no source event in the observed planning horizon; Task retained for operator review", row.id),
            });
        }
    }
    let known = known_external_ids(pool).await?;
    let conflicts = calendar_reconcile::classify(&applied, &observed, &known, &ubu_created_ids);
    // Carry the capture refusal through the existing diagnostic contract. The UI
    // groups by this backend reason rather than duplicating the ownership rule.
    diagnostics.extend(conflicts.iter()
        .filter(|conflict| conflict.conflict_type == "foreign")
        .filter_map(|conflict| super::calendar_capture::not_ownable_diagnostic(&conflict.external_id)));
    let status = if conflicts.is_empty() {
        "matched"
    } else if conflicts
        .iter()
        .any(|conflict| matches!(conflict.conflict_type.as_str(), "drifted" | "missing"))
    {
        "drifted"
    } else {
        "observed"
    };
    let reconciliation_id = UbuId::new(ObjectType::Snapshot).to_string();
    let now = state.planning_now().to_string();
    let payload = json!({
        "schema_version": CALENDAR_RECONCILIATION_SCHEMA_VERSION,
        "reconciliation_id": reconciliation_id,
        "preview_id": preview_id,
        "result_id": result_id,
        "status": status,
        "applied_events": applied,
        "out_of_range_events": out_of_range_events,
        "observed_events": observed,
        "known_external_ids": known,
        "conflicts": conflicts,
        "diagnostics": diagnostics,
        "repaired": false,
    });
    sqlx::query("INSERT INTO projection_reconciliations (id, preview_id, result_id, status, payload_json, created_at) VALUES (?, ?, ?, ?, ?, ?)")
        .bind(&reconciliation_id).bind(&preview_id).bind(result_id.as_deref().unwrap_or(""))
        .bind(status).bind(payload.to_string()).bind(now).execute(pool).await.map_err(internal)?;
    Ok(CalendarReconcileResponse {
        schema_version: CALENDAR_RECONCILIATION_SCHEMA_VERSION.into(),
        reconciliation_id,
        status: status.into(),
        conflicts,
        diagnostics,
    })
}

